class Solution {
public:
    string write(TreeNode* node) {
        if (!node) return "";
        string s = to_string(node->val);
        if (node->left || node->right) s += "(" + write(node->left) + ")";
        if (node->right) s += "(" + write(node->right) + ")";
        return s;
    }
    string tree2str(TreeNode* root) {
        return write(root);
    }
};
